// Hover previews for links: shows a card with the title and a summary from link_previews.js
// (generated by update_link_previews.py).
(function () {
    // Phones/tablets have no hover, so leave links alone there.
    if (!window.matchMedia("(hover: hover)").matches) return;

    const SHOW_DELAY_MS = 300;
    const HIDE_DELAY_MS = 250;

    const popup = document.createElement("div");
    popup.id = "link-preview";
    popup.hidden = true;
    document.body.appendChild(popup);

    let showTimer = null;
    let hideTimer = null;

    function fillPopup(preview) {
        popup.replaceChildren();
        const title = document.createElement("div");
        title.className = "preview-title";
        title.textContent = preview.title;
        popup.append(title);
        if (preview.authors) {
            const authors = document.createElement("div");
            authors.className = "preview-authors";
            authors.textContent = preview.authors;
            popup.append(authors);
        }
        const text = document.createElement("p");
        text.textContent = preview.text;
        popup.append(text);
        if (preview.math && window.renderMathInElement) { // raw LaTeX if the KaTeX CDN didn't load
            renderMathInElement(popup, {
                delimiters: [
                    { left: "$$", right: "$$", display: true },
                    { left: "$", right: "$", display: false },
                ],
                throwOnError: false,
            });
        }
    }

    function position(link) {
        const r = link.getBoundingClientRect();
        const w = popup.offsetWidth;
        const h = popup.offsetHeight;
        const gap = 8;
        const left = Math.min(Math.max(gap, r.left), window.innerWidth - w - gap);
        let top = r.bottom + gap;
        if (top + h > window.innerHeight - gap) top = Math.max(gap, r.top - h - gap);
        popup.style.left = `${left}px`;
        popup.style.top = `${top}px`;
    }

    function show(link, preview) {
        fillPopup(preview);
        popup.scrollTop = 0;
        popup.hidden = false;
        position(link);
    }

    function scheduleHide() {
        clearTimeout(showTimer);
        clearTimeout(hideTimer);
        hideTimer = setTimeout(() => { popup.hidden = true; }, HIDE_DELAY_MS);
    }

    document.querySelectorAll("main a[href]").forEach(link => {
        const preview = LINK_PREVIEWS[link.getAttribute("href")];
        if (!preview) return;
        link.addEventListener("mouseenter", () => {
            clearTimeout(hideTimer);
            clearTimeout(showTimer);
            showTimer = setTimeout(() => show(link, preview), SHOW_DELAY_MS);
        });
        link.addEventListener("mouseleave", scheduleHide);
    });

    // Let the mouse move into the popup (e.g. to scroll a long abstract) without it disappearing.
    popup.addEventListener("mouseenter", () => clearTimeout(hideTimer));
    popup.addEventListener("mouseleave", scheduleHide);
    window.addEventListener("scroll", () => { clearTimeout(showTimer); popup.hidden = true; }, { passive: true });
})();
